/** Markdown catalogue; `only` limits it to the components a page needs. */
function componentsMarkdown(only) {
	const wanted = only === undefined || only.length === 0 ? COMPONENTS : COMPONENTS.filter((one) => only.includes(one.id));
	const lines = [
		"# 组件清单（html 工具内置）",
		"",
		"页面骨架已自带整套样式与明暗两套配色：**只复制下面的片段、填内容，不要自己写 CSS，不要引入外部资源。**",
		""
	];
	for (const one of wanted) {
		lines.push(`## ${one.id} · ${one.name}`);
		lines.push("");
		lines.push(`什么时候用：${one.when}`);
		lines.push("");
		lines.push("```html");
		lines.push(one.snippet);
		lines.push("```");
		lines.push("");
	}
	return lines.join("\n");
}

/** Every class a snippet uses, for the test that proves the stylesheet covers it. */
function snippetClasses() {
	const out = new Set();
	for (const one of COMPONENTS) {
		for (const cls of one.classes) {
			out.add(cls);
		}
		for (const match of one.snippet.matchAll(/class="([^"]+)"/g)) {
			for (const cls of match[1].split(/\s+/)) {
				if (cls.length > 0) {
					out.add(cls);
				}
			}
		}
	}
	return [...out].sort();
}

/* --------------------------------------------------------------- template */

/**
 * A complete, self-contained page.
 *
 * Nothing here reaches the network, and nothing duplicates the shell's own
 * controls: the reader's actions belong to the app (export / share), not to a
 * button the page hides below the fold.
 */
function scratchDocument(options) {
	const title = escapeHtml(options.title === undefined ? "页面" : options.title);
	const accent = options.accent === undefined ? "#4d6bfe" : options.accent;
	const content = options.content === undefined ? "" : String(options.content);
	const eyebrow = options.eyebrow === undefined ? "" : String(options.eyebrow);
	return `<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title}</title>
<!-- 用 html 工具 components 里的片段填充；不要外链资源、不要自己加打印/分享按钮。 -->
<style>
${BASE_CSS.replace("__ACCENT__", accent)}
</style>
</head>
<body>
<div class="wrap">
<header class="page">
${eyebrow.length > 0 ? `<p class="eyebrow">${escapeHtml(eyebrow)}</p>` : ""}
<h1>${title}</h1>
</header>

<main>
${CONTENT_MARKER}
${content}
${SLOT_END_MARKER}
</main>

<footer class="page">
<p>单文件页面，离线可看</p>
</footer>
${END_MARKER}
</div>
</body>
</html>
`;
}

/**
 * Replace the content slot, or append a section to it.
 *
 * Both operations stay inside `<main>`: appending at the end of the page once
 * put sections after the footer, which renders below the "单文件页面" line and
 * outside the main landmark (verified on a real artifact). Older pages created
 * before the slot-end marker existed fall back to the page-end marker.
 */
function fillDocument(source, fragment, mode) {
	const html = String(fragment === undefined ? "" : fragment);
	const hasSlot = source.includes(CONTENT_MARKER);
	const slotEnd = source.indexOf(SLOT_END_MARKER);
	const start = hasSlot ? source.indexOf(CONTENT_MARKER) + CONTENT_MARKER.length : -1;
	if (!hasSlot) {
		throw new HtmlError("page has no dsh:content marker", "HTML_NO_MARKER");
	}
	if (mode === "append") {
		const insertAt = slotEnd >= 0 ? slotEnd : source.indexOf(END_MARKER);
		if (insertAt < 0) {
			throw new HtmlError("page has no slot-end or dsh:end marker to append to", "HTML_NO_MARKER");
		}
		return `${source.slice(0, insertAt)}${html}\n${source.slice(insertAt)}`;
	}
	const end = slotEnd >= 0 ? slotEnd : source.indexOf(END_MARKER);
	if (end < 0) {
		throw new HtmlError("page has no slot-end or dsh:end marker", "HTML_NO_MARKER");
	}
	if (end < start) {
		throw new HtmlError("slot-end comes before dsh:content", "HTML_NO_MARKER");
	}
	return `${source.slice(0, start)}\n${html}\n${source.slice(end)}`;
}

/* ------------------------------------------------------------------- check */

const EXTERNAL_PATTERNS = [
	{ re: /<script[^>]+src\s*=\s*["']https?:/gi, what: "远程 <script src>" },
	{ re: /<link[^>]+href\s*=\s*["']https?:/gi, what: "远程 <link href>" },
	{ re: /<(?:img|source|video|audio)[^>]+src\s*=\s*["']https?:/gi, what: "远程媒体 src" },
	{ re: /@import\s+(?:url\()?["']?https?:/gi, what: "@import 远程样式" },
	{ re: /url\(\s*["']?https?:/gi, what: "CSS url() 远程资源" },
	{ re: /@font-face[^}]*https?:/gis, what: "@font-face 远程字体" }
];

function lineOf(source, index) {
	let line = 1;
	for (let i = 0; i < index && i < source.length; i++) {
		if (source[i] === "\n") {
			line++;
		}
	}
	return line;
}

/**
 * Everything that makes a page fail on the device, in one list.
 *
 * `errors` mean "this will not render as intended"; `warnings` are the things
 * that usually mean someone pasted a desktop page into a phone viewer.
 */
function analyzeDocument(source, options) {
	const maxKb = options === undefined || options.maxKb === undefined ? DEFAULT_MAX_KB : options.maxKb;
	const sizeKb = Math.round((Buffer.byteLength(source, "utf8") / 1024) * 10) / 10;
	const errors = [];
	const warnings = [];
	const notes = [];

	if (sizeKb > maxKb) {
		errors.push(`文件 ${sizeKb}KB 超过上限 ${maxKb}KB：把大图换成 SVG/占位，或拆成多页`);
	}
	if (!/<meta[^>]+name\s*=\s*["']viewport["']/i.test(source)) {
		errors.push("缺少 <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">：手机会按桌面宽度渲染");
	}
	for (const pattern of EXTERNAL_PATTERNS) {
		pattern.re.lastIndex = 0;
		const match = pattern.re.exec(source);
		if (match !== null) {
			errors.push(`第 ${lineOf(source, match.index)} 行有${pattern.what}，设备上离线打不开（改成内联 data: 或纯 CSS/SVG）`);
		}
	}
	// The kit's stylesheet is the only <style> a page needs; another one means
	// the page is inventing its own look, which is exactly the drift this tool
	// exists to stop.
	if ((source.match(/<style[\s>]/gi) ?? []).length > 1) {
		warnings.push("页面里多了一个 <style>：优先用组件类；重复定义样式会让不同页面看起来不像一套");
	}
	if (/\bwindow\.print\s*\(/.test(source)) {
		warnings.push("页面调用了 window.print()：嵌入式 Web 里点不动，打印/导出请用壳的「导出」");
	}
	if (/onclick\s*=\s*["'][^"']*print/i.test(source)) {
		warnings.push("页面有打印按钮：嵌入式 Web 里点不动，删掉它，用壳的「导出」");
	}
	if (!/prefers-color-scheme/i.test(source)) {
		notes.push("没有 prefers-color-scheme：深色模式下会是一张白纸");
	}
	if (!/<h1[\s>]/i.test(source)) {
		warnings.push("没有 <h1>：预览与导出没有明显的标题层级");
	}
	const used = new Set();
	for (const match of source.matchAll(/class="([^"]+)"/g)) {
		for (const cls of match[1].split(/\s+/)) {
			if (cls.length > 0) {
				used.add(cls);
			}
		}
	}
	const known = new Set(snippetClasses().concat(["wrap", "page", "eyebrow", "lede"]));
	const unknown = [...used].filter((cls) => !known.has(cls) && !BASE_CSS.includes(`.${cls}`));
	if (unknown.length > 0) {
		warnings.push(`用了组件库之外的 class：${unknown.slice(0, 6).join(", ")}（要么改用组件，要么这些样式不会有任何效果）`);
	}
	return {
		ok: errors.length === 0,
		path: options === undefined || options.path === undefined ? "" : options.path,
		sizeKb,
		errors,
		warnings,
		notes
	};
}

/* -------------------------------------------------------------------- tool */

function parseArgs(args) {
	const action = String(args.action === undefined ? "" : args.action).trim();
	if (!["create", "fill", "check", "components"].includes(action)) {
		throw new HtmlError(`unknown action: ${action} (components | create | fill | check)`, "HTML_BAD_ARGS");
	}
	const out = {
		action,
		path: args.path === undefined ? "" : String(args.path).trim(),
		title: args.title === undefined ? "" : String(args.title),
		eyebrow: args.eyebrow === undefined ? "" : String(args.eyebrow),
		accent: args.accent === undefined ? "" : String(args.accent),
		html: args.html === undefined ? "" : String(args.html),
		mode: args.mode === undefined ? "replace" : String(args.mode),
		overwrite: args.overwrite === true,
		components: Array.isArray(args.components) ? args.components.map((one) => String(one)) : [],
		maxKb: typeof args.maxKb === "number" ? args.maxKb : undefined
	};
	if (action !== "components" && out.path.length === 0) {
		throw new HtmlError("path is required for create/fill/check", "HTML_BAD_ARGS");
	}
	if (out.accent.length > 0 && !/^#[0-9a-fA-F]{3,8}$/.test(out.accent)) {
		throw new HtmlError(`accent must be a hex colour: ${out.accent}`, "HTML_BAD_ARGS");
	}
	if (!["replace", "append"].includes(out.mode)) {
		throw new HtmlError(`mode must be replace or append: ${out.mode}`, "HTML_BAD_ARGS");
	}
	return out;
}

/** Resolve the session working directory exactly like the stock tools do. */
async function resolveWorkdir(ctx, exec) {
	return exec.agent === undefined ? process.cwd() : await ctx.workingDirectory.ensure(exec.agent, exec.signal);
}

function applyHtmlTool(ctx, config) {
	const tool = defineTool({
		name: "html",
		description:
			"Build an artifact page from a built-in component kit instead of writing CSS from scratch. " +
			"components returns the catalogue (hero, card, grid, stats, steps, checklist, table, callout, timeline, compare, bars, kv, fold, quote, code) with copy-paste snippets; " +
			"create writes a self-contained skeleton with the kit's stylesheet already inlined (mobile-first, light+dark, no external resources, no print/share buttons); " +
			"fill places snippets into the content slot (mode=append adds a section); " +
			"check reports what would break the page on this device (external links, missing viewport, missing print buttons, size, unknown classes). " +
			"Workflow: components → create → fill (one call per section) → check. " +
			"Paths are relative to the session workspace and must end in .html/.htm. " +
			"The app's preview already exports (long PNG / single-page PDF) and shares, so pages must not add their own buttons.",
		parameters: {
			action: {
				type: "string",
				required: true,
				description: "components | create | fill | check"
			},
			path: {
				type: "string",
				description: "page path relative to the workspace, e.g. fitness-plan.html (required for create/fill/check)"
			},
			title: {
				type: "string",
				description: "page title (create); becomes <title> and the <h1>"
			},
			eyebrow: {
				type: "string",
				description: "optional small line above the title (create)"
			},
			accent: {
				type: "string",
				description: "accent colour as #rrggbb (create)"
			},
			html: {
				type: "string",
				description: "HTML fragment built from catalogue snippets (create: initial content; fill: the section(s) to place)"
			},
			mode: {
				type: "string",
				description: "fill mode: replace (default) or append"
			},
			components: {
				type: "array",
				items: { type: "string" },
				description: "components action: limit the catalogue to these ids"
			},
			overwrite: {
				type: "boolean",
				description: "create over an existing file (default false)"
			},
			maxKb: {
				type: "number",
				description: "size ceiling for check (default 2048)"
			}
		},
		output: {
			schema: {
				type: "object",
				additionalProperties: false,
				properties: {
					ok: { type: "boolean", required: true },
					summary: { type: "string", required: true },
					path: { type: "string" },
					sizeKb: { type: "number" },
					next: { type: "string" },
					kind: { type: "string" },
					lines: { type: "array", items: { type: "string" } }
				}
			},
			render: (_args, value) => {
				if (value.kind === "markdown") {
					return [{ type: "text", text: value.summary }];
				}
				return [{
					type: "text",
					text: [value.summary]
						.concat(value.next === undefined ? [] : [`next: ${value.next}`])
						.concat(value.lines === undefined ? [] : value.lines)
						.join("\n")
				}];
			}
		},
		async execute(args, exec) {
			const input = parseArgs(args);
			const limit = input.maxKb === undefined ? config.maxKb : input.maxKb;

			if (input.action === "components") {
				return { ok: true, summary: componentsMarkdown(input.components), path: "", kind: "markdown" };
			}

			const workdir = await resolveWorkdir(ctx, exec);
			const page = resolvePagePath(workdir, input.path);

			if (input.action === "create") {
				if (existsSync(page.absolute) && !input.overwrite) {
					throw new HtmlError(`page already exists: ${page.relative} (pass overwrite:true to replace it)`, "HTML_EXISTS");
				}
				const document = scratchDocument({
					title: input.title.length > 0 ? input.title : page.relative,
					eyebrow: input.eyebrow,
					accent: input.accent.length > 0 ? input.accent : config.accent,
					content: input.html
				});
				const sizeKb = Math.round((Buffer.byteLength(document, "utf8") / 1024) * 10) / 10;
				if (sizeKb > limit) {
					throw new HtmlError(`page is ${sizeKb}KB, over the ${limit}KB ceiling`, "HTML_TOO_LARGE");
				}
				await mkdir(dirname(page.absolute), { recursive: true });
				await writeFile(page.absolute, document, "utf8");
				return {
					ok: true,
					summary: `created ${page.relative} (${sizeKb}KB) — kit stylesheet inlined, ready to preview`,
					path: page.relative,
					next: "fill sections in with action=fill (mode=append for each further section), then action=check"
				};
			}

			if (input.action === "fill") {
				if (!existsSync(page.absolute)) {
					throw new HtmlError(`page does not exist: ${page.relative}`, "HTML_MISSING");
				}
				const current = await readFile(page.absolute, "utf8");
				const next = fillDocument(current, input.html, input.mode);
				const sizeKb = Math.round((Buffer.byteLength(next, "utf8") / 1024) * 10) / 10;
				if (sizeKb > limit) {
					throw new HtmlError(`page would be ${sizeKb}KB, over the ${limit}KB ceiling`, "HTML_TOO_LARGE");
				}
				await writeFile(page.absolute, next, "utf8");
				return { ok: true, summary: `filled ${page.relative} (${sizeKb}KB)`, path: page.relative };
			}

			if (!existsSync(page.absolute)) {
				throw new HtmlError(`page does not exist: ${page.relative}`, "HTML_MISSING");
			}
			const source = await readFile(page.absolute, "utf8");
			const report = analyzeDocument(source, { maxKb: limit, path: page.relative });
			const lines = [];
			if (report.notes.length > 0) {
				lines.push(...report.notes.map((one) => `note: ${one}`));
			}
			if (report.warnings.length > 0) {
				lines.push(...report.warnings.map((one) => `warn: ${one}`));
			}
			if (report.errors.length > 0) {
				lines.push(...report.errors.map((one) => `error: ${one}`));
			}
			return {
				summary: report.ok
					? `checked ${report.path} (${report.sizeKb}KB) — ready for preview/export`
					: `checked ${report.path} (${report.sizeKb}KB) — ${report.errors.length} problem(s)`,
				ok: report.ok,
				sizeKb: report.sizeKb,
				lines
			};
		},
	});
	ctx.tools.register(tool);
}

function apply(ctx, config) {
	const resolved = config === undefined ? Config() : config;
	applyHtmlTool(ctx, {
		maxKb: resolved.maxKb,
		accent: resolved.accent
	});
}

export {
	BASE_CSS,
	COMPONENTS,
	CONTENT_MARKER,
	Config,
	END_MARKER,
	HtmlError,
	PAGE_EXTENSIONS,
	SLOT_END_MARKER,
	analyzeDocument,
	apply,
	componentsMarkdown,
	fillDocument,
	inject,
	name,
	parseArgs,
	resolvePagePath,
	scratchDocument,
	snippetClasses
};
